## Code Snippets – “What *not* to do” vs. “What to do”

```cpp
// 1. Avoid operator[] for lookup
auto it = map.find(key);
if (it != map.end()) {
    // use it->second
}

// 2. Avoid mutating keys
// WRONG: key is part of the map’s ordering
// key.value = newValue;   // ❌

// 3. Use try_emplace instead of emplace when key may exist
map.try_emplace(key, expensiveValue);

// 4. Reserve space before bulk insert
unordered_map.reserve(1000);

// 5. Custom key: hash + equality
struct Point {
    int x, y;
};
namespace std {
    template<> struct hash<Point> {
        size_t operator()(Point const& p) const noexcept {
            return std::hash<int>()(p.x) ^ (std::hash<int>()(p.y)<<1);
        }
    };
}
bool operator==(Point const& a, Point const& b) { return a.x==b.x && a.y==b.y; }

// 6. Safe node move
auto node = umap.extract(key); // node_type
// ... modify node.mapped()
umap.insert(std::move(node));

// 7. No default construction if not needed
// map.emplace(key, std::move(value));  // OK
```

